+import { Point2, type Point2Like } from "./point2"
+import type { PrecisionPolicy } from "./precision-policy"
+
+export class Polygon2 {
+  readonly points: readonly Point2[]
+
+  constructor(points: readonly Point2[]) {
+    if (points.length < 3) {
+      throw new Error("Polygon requires at least 3 points")
+    }
+    this.points = [...points]
+  }
+
+  static from(input: readonly Point2Like[]): Polygon2 {
+    return new Polygon2(input.map((point) => Point2.from(point)))
+  }
+
+  snap(policy: PrecisionPolicy): Polygon2 {
+    const result: Point2[] = []
+    for (const point of this.points) {
+      const snapped = point.snap(policy)
+      const previous = result[result.length - 1]
+      if (!previous || !previous.equals(snapped, policy)) {
+        result.push(snapped)
+      }
+    }
+    if (result.length >= 2) {
+      const first = result[0]
+      const last = result[result.length - 1]
+      if (first && last && first.equals(last, policy)) {
+        result.pop()
+      }
+    }
+    return new Polygon2(result)
+  }
+
+  containsPoint(point: Point2, policy: PrecisionPolicy): boolean {
+    let inside = false
+    const total = this.points.length
+    for (let index = 0; index < total; index += 1) {
+      const current = this.points[index]!
+      const next = this.points[(index + 1) % total]!
+      const intersects =
+        current.y > point.y !== next.y > point.y &&
+        point.x <
+          ((next.x - current.x) * (point.y - current.y)) / (next.y - current.y) +
+            current.x +
+            policy.eps
+      if (intersects) inside = !inside
+    }
+    return inside
+  }
+}
