+  readonly bounds: Rect2
+  readonly obstacles: readonly ObstacleModel[]
+  readonly connections: readonly RouteConnectionModel[]
+  readonly layerCount: number
+  readonly minTraceWidth: number
+  readonly minViaDiameter?: number
+  readonly outline?: Polygon2
+
+  constructor(input: SimpleRouteJson) {
+    this.source = input
+    this.bounds = Rect2.fromBounds(
+      input.bounds.minX,
+      input.bounds.minY,
+      input.bounds.maxX,
+      input.bounds.maxY,
+    )
+    this.obstacles = input.obstacles.map((obstacle) => new ObstacleModel(obstacle))
+    this.connections = input.connections.map(
+      (connection) => new RouteConnectionModel(connection),
+    )
+    this.layerCount = input.layerCount
+    this.minTraceWidth = input.minTraceWidth
+    this.minViaDiameter = input.minViaDiameter
+    this.outline = input.outline ? Polygon2.from(input.outline) : undefined
+  }
+
+  getLayerNames(): string[] {
+    const discovered = new Set<string>()
+    for (const obstacle of this.obstacles) {
+      for (const layer of obstacle.layers) discovered.add(layer)
+    }
+    for (const connection of this.connections) {
+      for (const point of connection.pointsToConnect) discovered.add(point.layer)
+    }
+
+    const canonical = this.defaultLayerNames()
+    for (const layer of canonical) discovered.add(layer)
+
+    return [...discovered]
+  }
+
+  defaultLayerNames(): string[] {
+    if (this.layerCount <= 0) return []
+    if (this.layerCount === 1) return ["top"]
+    if (this.layerCount === 2) return ["top", "bottom"]
+    const result = ["top"]
+    for (let index = 1; index < this.layerCount - 1; index += 1) {
+      result.push(`inner${index}`)
+    }
+    result.push("bottom")
+    return result
+  }
+
+  containsRectCenter(rect: Rect2, policy: PrecisionPolicy): boolean {
+    if (!this.outline) return true
+    return this.outline.snap(policy).containsPoint(rect.center.snap(policy), policy)
