import type { PrecisionPolicy } from "./precision-policy"

export class Interval1 {
  readonly min: number
  readonly max: number

  constructor(min: number, max: number) {
    if (max < min) {
      throw new Error(`Invalid interval: max ${max} < min ${min}`)
    }
    this.min = min
    this.max = max
  }

  get length(): number {
    return this.max - this.min
  }

  snap(policy: PrecisionPolicy): Interval1 {
    const min = policy.snap(this.min)
    const max = policy.snap(this.max)
    return new Interval1(Math.min(min, max), Math.max(min, max))
  }

  intersects(other: Interval1, policy: PrecisionPolicy): boolean {
    return (
      policy.greaterThan(this.max, other.min) &&
      policy.greaterThan(other.max, this.min)
    )
  }

  intersection(other: Interval1, policy: PrecisionPolicy): Interval1 | null {
    const min = Math.max(this.min, other.min)
    const max = Math.min(this.max, other.max)
    if (!policy.greaterThan(max, min)) return null
    return new Interval1(min, max)
  }

  touches(other: Interval1, policy: PrecisionPolicy): boolean {
    return (
      this.intersects(other, policy) ||
      policy.equal(this.max, other.min) ||
      policy.equal(other.max, this.min)
    )
  }
}

