import { Interval1 } from "./interval1"
import { Point2 } from "./point2"
import type { PrecisionPolicy } from "./precision-policy"

export interface Rect2Like {
  x: number
  y: number
  width: number
  height: number
}

export class Rect2 {
  readonly x: number
  readonly y: number
  readonly width: number
  readonly height: number

  constructor(x: number, y: number, width: number, height: number) {
    if (width < 0 || height < 0) {
      throw new Error(`Invalid rect size: ${width} x ${height}`)
    }
    this.x = x
    this.y = y
    this.width = width
    this.height = height
  }

  static from(input: Rect2Like): Rect2 {
    return new Rect2(input.x, input.y, input.width, input.height)
  }

  static fromBounds(minX: number, minY: number, maxX: number, maxY: number): Rect2 {
    return new Rect2(minX, minY, maxX - minX, maxY - minY)
  }

  get minX(): number {
    return this.x
  }

  get minY(): number {
    return this.y
  }

  get maxX(): number {
    return this.x + this.width
  }

  get maxY(): number {
    return this.y + this.height
  }

  get center(): Point2 {
    return new Point2(this.x + this.width / 2, this.y + this.height / 2)
  }

  get xInterval(): Interval1 {
    return new Interval1(this.minX, this.maxX)
  }

  get yInterval(): Interval1 {
    return new Interval1(this.minY, this.maxY)
  }

  snap(policy: PrecisionPolicy): Rect2 {
    const minX = policy.snap(this.minX)
    const minY = policy.snap(this.minY)
    const maxX = policy.snap(this.maxX)
    const maxY = policy.snap(this.maxY)
    return Rect2.fromBounds(Math.min(minX, maxX), Math.min(minY, maxY), Math.max(minX, maxX), Math.max(minY, maxY))
  }

  area(): number {
    return this.width * this.height
  }

  containsPoint(point: Point2, policy: PrecisionPolicy): boolean {
    return (
      policy.greaterThanOrEqual(point.x, this.minX) &&
      policy.lessThanOrEqual(point.x, this.maxX) &&
      policy.greaterThanOrEqual(point.y, this.minY) &&
      policy.lessThanOrEqual(point.y, this.maxY)
    )
  }

  overlaps(other: Rect2, policy: PrecisionPolicy): boolean {
    return (
      policy.greaterThan(this.maxX, other.minX) &&
      policy.greaterThan(other.maxX, this.minX) &&
      policy.greaterThan(this.maxY, other.minY) &&
      policy.greaterThan(other.maxY, this.minY)
    )
  }

  intersection(other: Rect2, policy: PrecisionPolicy): Rect2 | null {
    const minX = Math.max(this.minX, other.minX)
    const minY = Math.max(this.minY, other.minY)
    const maxX = Math.min(this.maxX, other.maxX)
    const maxY = Math.min(this.maxY, other.maxY)
    if (!policy.greaterThan(maxX, minX) || !policy.greaterThan(maxY, minY)) {
      return null
    }
    return Rect2.fromBounds(minX, minY, maxX, maxY)
  }

  touchesHorizontally(other: Rect2, policy: PrecisionPolicy): boolean {
    return (
      policy.equal(this.maxX, other.minX) &&
      policy.equal(this.minY, other.minY) &&
      policy.equal(this.height, other.height)
    )
  }

  touchesVertically(other: Rect2, policy: PrecisionPolicy): boolean {
    return (
      policy.equal(this.maxY, other.minY) &&
      policy.equal(this.minX, other.minX) &&
      policy.equal(this.width, other.width)
    )
  }

  mergeHorizontally(other: Rect2, policy: PrecisionPolicy): Rect2 | null {
    if (!this.touchesHorizontally(other, policy)) return null
    return new Rect2(this.minX, this.minY, other.maxX - this.minX, this.height)
  }

  mergeVertically(other: Rect2, policy: PrecisionPolicy): Rect2 | null {
    if (!this.touchesVertically(other, policy)) return null
    return new Rect2(this.minX, this.minY, this.width, other.maxY - this.minY)
  }

  subtract(other: Rect2, policy: PrecisionPolicy): Rect2[] {
    const overlap = this.intersection(other, policy)
    if (!overlap) return [this]

    const result: Rect2[] = []
    if (policy.greaterThan(overlap.minX, this.minX)) {
      result.push(Rect2.fromBounds(this.minX, this.minY, overlap.minX, this.maxY))
    }
    if (policy.greaterThan(this.maxX, overlap.maxX)) {
      result.push(Rect2.fromBounds(overlap.maxX, this.minY, this.maxX, this.maxY))
    }
    if (policy.greaterThan(overlap.minY, this.minY)) {
      result.push(Rect2.fromBounds(overlap.minX, this.minY, overlap.maxX, overlap.minY))
    }
    if (policy.greaterThan(this.maxY, overlap.maxY)) {
      result.push(Rect2.fromBounds(overlap.minX, overlap.maxY, overlap.maxX, this.maxY))
    }
    return result.filter(
      (rect) =>
        policy.greaterThan(rect.width, 0) && policy.greaterThan(rect.height, 0),
    )
  }

  distanceToPoint(point: Point2): number {
    if (
      point.x >= this.minX &&
      point.x <= this.maxX &&
      point.y >= this.minY &&
      point.y <= this.maxY
    ) {
      return Math.min(
        point.x - this.minX,
        this.maxX - point.x,
        point.y - this.minY,
        this.maxY - point.y,
      )
    }

    const dx =
      point.x < this.minX ? this.minX - point.x : point.x > this.maxX ? point.x - this.maxX : 0
    const dy =
      point.y < this.minY ? this.minY - point.y : point.y > this.maxY ? point.y - this.maxY : 0
    if (dx === 0) return dy
    if (dy === 0) return dx
    return Math.hypot(dx, dy)
  }

  toJSON(): Rect2Like {
    return {
      x: this.x,
      y: this.y,
      width: this.width,
      height: this.height,
    }
  }
}

