import type { PrecisionPolicy } from "@ohmx/geometry"
import { DEFAULT_PRECISION_POLICY } from "@ohmx/geometry"
import { RouteProblem } from "./domain/route-problem"
import { RectDiffEngine, type RectDiffEngineInput } from "./solver/rectdiff-engine"
import type { GridFill3DOptions } from "./solver/grid-fill-options"
import type { CapacityMeshNode } from "./types/capacity-mesh-types"
import type { SimpleRouteJson } from "./types/srj-types"

export interface RectDiffPipelineInput {
  simpleRouteJson: SimpleRouteJson
  gridOptions?: Partial<GridFill3DOptions>
  precisionPolicy?: PrecisionPolicy
}

export class RectDiffPipeline {
  readonly inputProblem: RectDiffPipelineInput
  readonly precisionPolicy: PrecisionPolicy

  private engine: RectDiffEngine
  solved = false

  constructor(inputProblem: RectDiffPipelineInput) {
    this.inputProblem = inputProblem
    this.precisionPolicy = inputProblem.precisionPolicy ?? DEFAULT_PRECISION_POLICY
    this.engine = this.createEngine()
  }

  private createEngine(): RectDiffEngine {
    const problem = new RouteProblem(this.inputProblem.simpleRouteJson)
    const engineInput: RectDiffEngineInput = {
      problem,
      gridOptions: this.inputProblem.gridOptions,
      precisionPolicy: this.precisionPolicy,
    }
    return new RectDiffEngine(engineInput)
  }

  setup(): void {
    this.engine.setup()
    this.solved = this.engine.solved()
  }

  step(): void {
    this.engine.step()
    this.solved = this.engine.solved()
  }

  solve(): void {
    this.engine.solve()
    this.solved = true
  }

  computeProgress(): number {
    return this.engine.progress()
  }

  getOutput(): { meshNodes: CapacityMeshNode[] } {
    return this.engine.getOutput()
  }

  visualize(): {
    title: string
    coordinateSystem: "cartesian"
    rects: Array<{
      center: { x: number; y: number }
      width: number
      height: number
      layer: string
    }>
  } {
    const meshNodes = this.getOutput().meshNodes
    return {
      title: "RectDiffPipeline",
      coordinateSystem: "cartesian",
      rects: meshNodes.map((node) => ({
        center: node.center,
        width: node.width,
        height: node.height,
        layer: node.layer,
      })),
    }
  }
}

