export interface PrecisionPolicyInit {
  eps?: number
  snapStep?: number
}

export class PrecisionPolicy {
  static readonly DEFAULT_EPS = 1e-6

  static readonly DEFAULT_SNAP_STEP = 1e-6

  readonly eps: number
  readonly snapStep: number

  constructor(init: PrecisionPolicyInit = {}) {
    this.eps = init.eps ?? PrecisionPolicy.DEFAULT_EPS
    this.snapStep = init.snapStep ?? PrecisionPolicy.DEFAULT_SNAP_STEP
  }

  with(init: PrecisionPolicyInit): PrecisionPolicy {
    return new PrecisionPolicy({
      eps: init.eps ?? this.eps,
      snapStep: init.snapStep ?? this.snapStep,
    })
  }

  snap(value: number): number {
    return Math.round(value / this.snapStep) * this.snapStep
  }

  isZero(value: number): boolean {
    return Math.abs(value) <= this.eps
  }

  equal(a: number, b: number): boolean {
    return Math.abs(a - b) <= this.eps
  }

  greaterThan(a: number, b: number): boolean {
    return a > b + this.eps
  }

  greaterThanOrEqual(a: number, b: number): boolean {
    return a > b - this.eps
  }

  lessThan(a: number, b: number): boolean {
    return a < b - this.eps
  }

  lessThanOrEqual(a: number, b: number): boolean {
    return a < b + this.eps
  }

  clamp(value: number, min: number, max: number): number {
    return Math.max(min, Math.min(max, value))
  }

  uniqueSorted(values: readonly number[]): number[] {
    const snapped = values.map((value) => this.snap(value)).sort((a, b) => a - b)
    const result: number[] = []
    for (const value of snapped) {
      const previous = result[result.length - 1]
      if (previous === undefined || !this.equal(previous, value)) {
        result.push(value)
      }
    }
    return result
  }
}

export const DEFAULT_PRECISION_POLICY = new PrecisionPolicy()

