import { Point2 } from "./point2"
import { Rect2 } from "./rect2"

export class Segment2 {
  readonly start: Point2
  readonly end: Point2

  constructor(start: Point2, end: Point2) {
    this.start = start
    this.end = end
  }

  midpoint(): Point2 {
    return this.start.midpoint(this.end)
  }

  length(): number {
    return this.start.distanceTo(this.end)
  }

  distanceToRect(rect: Rect2): number {
    const steps = 24
    let minDistance = Number.POSITIVE_INFINITY
    for (let index = 0; index <= steps; index += 1) {
      const t = index / steps
      const point = new Point2(
        this.start.x + (this.end.x - this.start.x) * t,
        this.start.y + (this.end.y - this.start.y) * t,
      )
      minDistance = Math.min(minDistance, rect.distanceToPoint(point))
    }
    return minDistance
  }
}

