import type { PrecisionPolicy } from "./precision-policy"

export interface Point2Like {
  x: number
  y: number
}

export class Point2 {
  readonly x: number
  readonly y: number

  constructor(x: number, y: number) {
    this.x = x
    this.y = y
  }

  static from(input: Point2Like): Point2 {
    return new Point2(input.x, input.y)
  }

  withX(x: number): Point2 {
    return new Point2(x, this.y)
  }

  withY(y: number): Point2 {
    return new Point2(this.x, y)
  }

  snap(policy: PrecisionPolicy): Point2 {
    return new Point2(policy.snap(this.x), policy.snap(this.y))
  }

  equals(other: Point2, policy: PrecisionPolicy): boolean {
    return policy.equal(this.x, other.x) && policy.equal(this.y, other.y)
  }

  distanceTo(other: Point2): number {
    return Math.hypot(this.x - other.x, this.y - other.y)
  }

  midpoint(other: Point2): Point2 {
    return new Point2((this.x + other.x) / 2, (this.y + other.y) / 2)
  }

  toJSON(): Point2Like {
    return { x: this.x, y: this.y }
  }
}

