export class LayerSet {
  readonly values: readonly number[]

  constructor(values: readonly number[]) {
    this.values = [...values].sort((a, b) => a - b)
  }

  static from(values: readonly number[]): LayerSet {
    return new LayerSet([...new Set(values)])
  }

  static full(count: number): LayerSet {
    return new LayerSet(Array.from({ length: count }, (_, index) => index))
  }

  isEmpty(): boolean {
    return this.values.length === 0
  }

  size(): number {
    return this.values.length
  }

  equals(other: LayerSet): boolean {
    if (this.values.length !== other.values.length) return false
    return this.values.every((value, index) => value === other.values[index])
  }

  toArray(): number[] {
    return [...this.values]
  }

  toKey(): string {
    return this.values.join(",")
  }
}

