import {
  DEFAULT_PRECISION_POLICY,
  type PrecisionPolicy,
  Rect2,
} from "@ohmx/geometry"
import { LayerSet } from "../domain/layer-set"
import { MeshNodeModel } from "../domain/mesh-node"
import { RouteProblem } from "../domain/route-problem"
import type { CapacityMeshNode } from "../types/capacity-mesh-types"
import {
  DEFAULT_GRID_OPTIONS,
  type GridFill3DOptions,
} from "./grid-fill-options"
import { SolverState } from "./solver-state"

export interface RectDiffEngineInput {
  problem: RouteProblem
  gridOptions?: Partial<GridFill3DOptions>
  precisionPolicy?: PrecisionPolicy
}

export class RectDiffEngine {
  readonly problem: RouteProblem
  readonly options: GridFill3DOptions
  readonly precision: PrecisionPolicy

  private state: SolverState = new SolverState()
  private setupComplete = false

  constructor(input: RectDiffEngineInput) {
    this.problem = input.problem
    this.precision = input.precisionPolicy ?? DEFAULT_PRECISION_POLICY
    this.options = {
      ...DEFAULT_GRID_OPTIONS,
      ...input.gridOptions,
      minSingle: {
        ...DEFAULT_GRID_OPTIONS.minSingle,
        ...input.gridOptions?.minSingle,
      },
      minMulti: {
        ...DEFAULT_GRID_OPTIONS.minMulti,
        ...input.gridOptions?.minMulti,
      },
    }
  }

  setup(): void {
    const cells = buildCells(this.problem, this.precision)
    this.state = SolverState.initial(cells)
    this.setupComplete = true
  }

  step(): void {
    if (!this.setupComplete) this.setup()
    const { current, next } = this.state.consumePending()
    if (!current) {
      this.state = this.state.merged(this.precision)
      return
    }

    this.state = next
    const layers = computeAvailableLayers(
      current,
      this.problem,
      this.precision,
      this.options,
    )
    if (layers.isEmpty()) {
      this.state = this.state.reject(current)
      return
    }

    const minimum = getMinimumForLayers(layers, this.options)
    if (
      this.precision.lessThan(current.width, minimum.width) ||
      this.precision.lessThan(current.height, minimum.height)
    ) {
      this.state = this.state.reject(current)
      return
    }

    const node = new MeshNodeModel(
      `node-${this.state.acceptedNodes.length}`,
      current.snap(this.precision),
      layers,
    )
    this.state = this.state.accept(node)
  }

  solve(): void {
    while (!this.solved()) {
      this.step()
    }
  }

  solved(): boolean {
    return this.setupComplete && this.state.pendingCells.length === 0
  }

  progress(): number {
    if (!this.setupComplete) return 0
    const processed = this.state.totalCells - this.state.pendingCells.length
    return this.state.totalCells === 0 ? 1 : processed / this.state.totalCells
  }

  getOutput(): { meshNodes: CapacityMeshNode[] } {
    const nodes =
      this.state.pendingCells.length === 0
        ? this.state.merged(this.precision).acceptedNodes
        : this.state.acceptedNodes
    return {
      meshNodes: nodes.map((node) => node.toCapacityMeshNode()),
    }
  }
}

function buildCells(problem: RouteProblem, precision: PrecisionPolicy): Rect2[] {
  const xs = [problem.bounds.minX, problem.bounds.maxX]
  const ys = [problem.bounds.minY, problem.bounds.maxY]

  for (const obstacle of problem.obstacles) {
    xs.push(obstacle.rect.minX, obstacle.rect.maxX)
    ys.push(obstacle.rect.minY, obstacle.rect.maxY)
  }

  if (problem.outline) {
    for (const point of problem.outline.points) {
      xs.push(point.x)
      ys.push(point.y)
    }
  }

  const xCuts = precision.uniqueSorted(xs)
  const yCuts = precision.uniqueSorted(ys)
  const cells: Rect2[] = []
  for (let xIndex = 0; xIndex < xCuts.length - 1; xIndex += 1) {
    for (let yIndex = 0; yIndex < yCuts.length - 1; yIndex += 1) {
      const cell = Rect2.fromBounds(
        xCuts[xIndex]!,
        yCuts[yIndex]!,
        xCuts[xIndex + 1]!,
        yCuts[yIndex + 1]!,
      ).snap(precision)
      if (
        !precision.greaterThan(cell.width, 0) ||
        !precision.greaterThan(cell.height, 0)
      ) {
        continue
      }
      if (!problem.containsRectCenter(cell, precision)) continue
      cells.push(cell)
    }
  }
  return cells
}

function computeAvailableLayers(
  cell: Rect2,
  problem: RouteProblem,
  precision: PrecisionPolicy,
  options: GridFill3DOptions,
): LayerSet {
  const available: number[] = []
  const layerNames = problem.defaultLayerNames()
  for (let layerIndex = 0; layerIndex < problem.layerCount; layerIndex += 1) {
    let blocked = false
    for (const obstacle of problem.obstacles) {
      const zLayers = obstacle.zLayers ?? obstacle.layers.map((layer) => layerNames.indexOf(layer)).filter((value) => value >= 0)
      if (!zLayers.includes(layerIndex)) continue
      if (cell.overlaps(obstacle.rect.snap(precision), precision)) {
        blocked = true
        break
      }
    }
    if (!blocked) {
      available.push(layerIndex)
    }
  }

  if (options.maxMultiLayerSpan && available.length > options.maxMultiLayerSpan) {
    return LayerSet.from(available.slice(0, options.maxMultiLayerSpan))
  }
  return LayerSet.from(available)
}

function getMinimumForLayers(
  layers: LayerSet,
  options: GridFill3DOptions,
): { width: number; height: number } {
  if (
    options.preferMultiLayer &&
    layers.size() >= options.minMulti.minLayers
  ) {
    return options.minMulti
  }
  return options.minSingle
}

