import { Point2, Polygon2, Rect2, type PrecisionPolicy } from "@ohmx/geometry"
import type {
  Obstacle,
  SimpleRouteConnection,
  SimpleRouteConnectionPoint,
  SimpleRouteJson,
} from "../types/srj-types"

export class ConnectionPointModel {
  readonly point: Point2
  readonly layer: string
  readonly pointId?: string
  readonly pcbPortId?: string

  constructor(input: SimpleRouteConnectionPoint) {
    this.point = new Point2(input.x, input.y)
    this.layer = input.layer
    this.pointId = input.pointId
    this.pcbPortId = input.pcb_port_id
  }
}

export class RouteConnectionModel {
  readonly name: string
  readonly netConnectionName?: string
  readonly nominalTraceWidth?: number
  readonly pointsToConnect: readonly ConnectionPointModel[]

  constructor(input: SimpleRouteConnection) {
    this.name = input.name
    this.netConnectionName = input.netConnectionName
    this.nominalTraceWidth = input.nominalTraceWidth
    this.pointsToConnect = input.pointsToConnect.map(
      (point) => new ConnectionPointModel(point),
    )
  }
}

export class ObstacleModel {
  readonly layers: readonly string[]
  readonly zLayers?: readonly number[]
  readonly rect: Rect2
  readonly connectedTo: readonly string[]

  constructor(input: Obstacle) {
    this.layers = [...input.layers]
    this.zLayers = input.zLayers ? [...input.zLayers] : undefined
    this.rect = new Rect2(
      input.center.x - input.width / 2,
      input.center.y - input.height / 2,
      input.width,
      input.height,
    )
    this.connectedTo = [...input.connectedTo]
  }
}

export class RouteProblem {
  readonly source: SimpleRouteJson
  readonly bounds: Rect2
  readonly obstacles: readonly ObstacleModel[]
  readonly connections: readonly RouteConnectionModel[]
  readonly layerCount: number
  readonly minTraceWidth: number
  readonly minViaDiameter?: number
  readonly outline?: Polygon2

  constructor(input: SimpleRouteJson) {
    this.source = input
    this.bounds = Rect2.fromBounds(
      input.bounds.minX,
      input.bounds.minY,
      input.bounds.maxX,
      input.bounds.maxY,
    )
    this.obstacles = input.obstacles.map((obstacle) => new ObstacleModel(obstacle))
    this.connections = input.connections.map(
      (connection) => new RouteConnectionModel(connection),
    )
    this.layerCount = input.layerCount
    this.minTraceWidth = input.minTraceWidth
    this.minViaDiameter = input.minViaDiameter
    this.outline = input.outline ? Polygon2.from(input.outline) : undefined
  }

  getLayerNames(): string[] {
    const discovered = new Set<string>()
    for (const obstacle of this.obstacles) {
      for (const layer of obstacle.layers) discovered.add(layer)
    }
    for (const connection of this.connections) {
      for (const point of connection.pointsToConnect) discovered.add(point.layer)
    }

    const canonical = this.defaultLayerNames()
    for (const layer of canonical) discovered.add(layer)

    return [...discovered]
  }

  defaultLayerNames(): string[] {
    if (this.layerCount <= 0) return []
    if (this.layerCount === 1) return ["top"]
    if (this.layerCount === 2) return ["top", "bottom"]
    const result = ["top"]
    for (let index = 1; index < this.layerCount - 1; index += 1) {
      result.push(`inner${index}`)
    }
    result.push("bottom")
    return result
  }

  containsRectCenter(rect: Rect2, policy: PrecisionPolicy): boolean {
    if (!this.outline) return true
    return this.outline.snap(policy).containsPoint(rect.center.snap(policy), policy)
  }
}

