+  gridOptions?: Partial<GridFill3DOptions>,
+): GridFill3DOptions {
+  return {
+    ...DEFAULT_GRID_OPTIONS,
+    ...gridOptions,
+    minSingle: {
+      ...DEFAULT_GRID_OPTIONS.minSingle,
+      ...gridOptions?.minSingle,
+    },
+    minMulti: {
+      ...DEFAULT_GRID_OPTIONS.minMulti,
+      ...gridOptions?.minMulti,
+    },
+  }
+}
+
+export function resolvePrecisionPolicy(
+  precisionPolicy?: PrecisionPolicy,
+): PrecisionPolicy {
+  return precisionPolicy ?? DEFAULT_PRECISION_POLICY
+}
+
+export function buildCells(problem: RouteProblem, precision: PrecisionPolicy): Rect2[] {
+  const xs = [problem.bounds.minX, problem.bounds.maxX]
+  const ys = [problem.bounds.minY, problem.bounds.maxY]
+
+  for (const obstacle of problem.obstacles) {
+    xs.push(obstacle.rect.minX, obstacle.rect.maxX)
+    ys.push(obstacle.rect.minY, obstacle.rect.maxY)
+  }
+
+  if (problem.outline) {
+    for (const point of problem.outline.points) {
+      xs.push(point.x)
+      ys.push(point.y)
+    }
+  }
+
+  const xCuts = precision.uniqueSorted(xs)
+  const yCuts = precision.uniqueSorted(ys)
+  const cells: Rect2[] = []
+  for (let xIndex = 0; xIndex < xCuts.length - 1; xIndex += 1) {
+    for (let yIndex = 0; yIndex < yCuts.length - 1; yIndex += 1) {
+      const cell = Rect2.fromBounds(
+        xCuts[xIndex]!,
+        yCuts[yIndex]!,
+        xCuts[xIndex + 1]!,
+        yCuts[yIndex + 1]!,
+      ).snap(precision)
+      if (
+        !precision.greaterThan(cell.width, 0) ||
+        !precision.greaterThan(cell.height, 0)
+      ) {
+        continue
+      }
+      if (!problem.containsRectCenter(cell, precision)) continue
+      cells.push(cell)
+    }
+  }
+  return cells
+}
+
+export function computeAvailableLayers(
+  cell: Rect2,
+  problem: RouteProblem,
+  precision: PrecisionPolicy,
+  options: GridFill3DOptions,
+): LayerSet {
+  const available: number[] = []
+  const layerNames = problem.defaultLayerNames()
+
+  for (let layerIndex = 0; layerIndex < problem.layerCount; layerIndex += 1) {
+    let blocked = false
+    for (const obstacle of problem.obstacles) {
+      const zLayers =
+        obstacle.zLayers ??
+        obstacle.layers
+          .map((layer) => layerNames.indexOf(layer))
+          .filter((value) => value >= 0)
+      if (!zLayers.includes(layerIndex)) continue
+      if (cell.overlaps(obstacle.rect.snap(precision), precision)) {
+        blocked = true
+        break
+      }
+    }
+    if (!blocked) {
+      available.push(layerIndex)
+    }
+  }
+
+  if (options.maxMultiLayerSpan && available.length > options.maxMultiLayerSpan) {
+    return LayerSet.from(available.slice(0, options.maxMultiLayerSpan))
+  }
+  return LayerSet.from(available)
+}
+
+export function getMinimumForLayers(
+  layers: LayerSet,
+  options: GridFill3DOptions,
+): { width: number; height: number } {
+  if (
+    options.preferMultiLayer &&
+    layers.size() >= options.minMulti.minLayers
+  ) {
+    return options.minMulti
+  }
+  return options.minSingle
+}
