import type { GraphicsObject } from "graphics-debug"
import type { MeshNodeModel } from "../domain/mesh-node"
import type { RouteProblem } from "../domain/route-problem"
import type { Rect2 } from "@ohmx/geometry"

function baseGraphics(title: string): GraphicsObject {
  return {
    title,
    coordinateSystem: "cartesian",
    rects: [],
    lines: [],
    points: [],
    circles: [],
    texts: [],
  }
}

export function visualizeProblem(
  title: string,
  problem: RouteProblem,
): GraphicsObject {
  const graphics = baseGraphics(title)
  graphics.rects?.push({
    center: problem.bounds.center.toJSON(),
    width: problem.bounds.width,
    height: problem.bounds.height,
    stroke: "rgba(15, 23, 42, 0.7)",
  })

  for (const obstacle of problem.obstacles) {
    graphics.rects?.push({
      center: obstacle.rect.center.toJSON(),
      width: obstacle.rect.width,
      height: obstacle.rect.height,
      fill: "rgba(220, 38, 38, 0.25)",
      stroke: "rgba(153, 27, 27, 0.8)",
    })
  }

  if (problem.outline) {
    const points = [...problem.outline.points, problem.outline.points[0]!].map(
      (point) => point.toJSON(),
    )
    graphics.lines?.push({
      points,
      strokeColor: "rgba(37, 99, 235, 0.9)",
    })
  }

  return graphics
}

export function visualizeCells(
  title: string,
  problem: RouteProblem,
  cells: readonly Rect2[],
): GraphicsObject {
  const graphics = visualizeProblem(title, problem)
  for (const cell of cells) {
    graphics.rects?.push({
      center: cell.center.toJSON(),
      width: cell.width,
      height: cell.height,
      fill: "rgba(148, 163, 184, 0.12)",
      stroke: "rgba(100, 116, 139, 0.4)",
    })
  }
  return graphics
}

export function visualizeMeshNodes(
  title: string,
  problem: RouteProblem,
  nodes: readonly MeshNodeModel[],
  rejectedCells: readonly Rect2[] = [],
): GraphicsObject {
  const graphics = visualizeProblem(title, problem)
  for (const cell of rejectedCells) {
    graphics.rects?.push({
      center: cell.center.toJSON(),
      width: cell.width,
      height: cell.height,
      fill: "rgba(251, 146, 60, 0.08)",
      stroke: "rgba(249, 115, 22, 0.35)",
    })
  }
  for (const node of nodes) {
    graphics.rects?.push({
      center: node.rect.center.toJSON(),
      width: node.rect.width,
      height: node.rect.height,
      fill: "rgba(16, 185, 129, 0.16)",
      stroke: "rgba(5, 150, 105, 0.65)",
      layer: `z${node.layers.toKey()}`,
      label: node.layers.toKey(),
    })
  }
  return graphics
}

import { BaseSolver } from "@tscircuit/solver-utils"
import { buildCells } from "./rectdiff-core"
import { visualizeCells } from "./graphics"
import type {
  CellDecompositionOutput,
  NormalizedProblemOutput,
} from "./pipeline-types"

export interface CellDecompositionSolverInput extends NormalizedProblemOutput {}

export class CellDecompositionSolver extends BaseSolver {
  private output?: CellDecompositionOutput

  constructor(private readonly input: CellDecompositionSolverInput) {
    super()
  }

  override _step() {
    if (!this.output) {
      this.output = {
        ...this.input,
        candidateCells: buildCells(
          this.input.problem,
          this.input.precisionPolicy,
        ),
      }
    }
    this.solved = true
  }

  override getOutput(): CellDecompositionOutput {
    if (!this.output) {
      throw new Error("CellDecompositionSolver output requested before solve")
    }
    return this.output
  }

  override getConstructorParams() {
    return [this.input]
  }

  override visualize() {
    if (!this.output) return super.visualize()
    return visualizeCells(
      "Cell Decomposition",
      this.output.problem,
      this.output.candidateCells,
    )
  }
}

import { BaseSolver } from "@tscircuit/solver-utils"
