import type { GapFillOutput, MeshGenerationOutput } from "./pipeline-types"

export interface GapFillSolverInput extends MeshGenerationOutput {}

export class GapFillSolver extends BaseSolver {
  private output?: GapFillOutput

  constructor(private readonly input: GapFillSolverInput) {
    super()
  }

  override _step() {
    if (!this.output) {
      this.output = {
        ...this.input,
        outputNodes: [...this.input.meshNodes],
      }
    }
    this.solved = true
  }

  override getOutput(): GapFillOutput {
    if (!this.output) {
      throw new Error("GapFillSolver output requested before solve")
    }
    return this.output
  }

  override getConstructorParams() {
    return [this.input]
  }

  override visualize() {
    if (!this.output) return super.visualize()
    return visualizeMeshNodes(
      "Gap Fill",
      this.output.problem,
      this.output.outputNodes,
      this.output.rejectedCells,
    )
  }
}

