    if (!this.output) {
      throw new Error("ProblemNormalizationSolver output requested before solve")
    }
    return this.output
  }

  override getConstructorParams() {
    return [this.input]
  }

  override visualize() {
    if (!this.output) return super.visualize()
    return visualizeProblem("Problem Normalization", this.output.problem)
  }
