import { BaseSolver } from "@tscircuit/solver-utils"
import { MeshNodeModel } from "../domain/mesh-node"
import { SolverState } from "./solver-state"
import {
  computeAvailableLayers,
  getMinimumForLayers,
} from "./rectdiff-core"
import { visualizeMeshNodes } from "./graphics"
import type {
  CellDecompositionOutput,
  MeshGenerationOutput,
} from "./pipeline-types"

export interface MeshGenerationSolverInput extends CellDecompositionOutput {}

export class MeshGenerationSolver extends BaseSolver {
  private state = new SolverState()

  constructor(private readonly input: MeshGenerationSolverInput) {
    super()
  }

  override _setup() {
    this.state = SolverState.initial(this.input.candidateCells)
  }

  override _step() {
    const { current, next } = this.state.consumePending()
    if (!current) {
      this.state = this.state.merged(this.input.precisionPolicy)
      this.solved = true
      return
    }

    this.state = next
    const layers = computeAvailableLayers(
      current,
      this.input.problem,
      this.input.precisionPolicy,
      this.input.gridOptions,
    )
    if (layers.isEmpty()) {
      this.state = this.state.reject(current)
      return
    }

    const minimum = getMinimumForLayers(layers, this.input.gridOptions)
    if (
      this.input.precisionPolicy.lessThan(current.width, minimum.width) ||
      this.input.precisionPolicy.lessThan(current.height, minimum.height)
    ) {
      this.state = this.state.reject(current)
      return
    }

    const node = new MeshNodeModel(
      `node-${this.state.acceptedNodes.length}`,
      current.snap(this.input.precisionPolicy),
      layers,
    )
    this.state = this.state.accept(node)
  }

  override computeProgress() {
    return this.state.progress()
  }

  override getOutput(): MeshGenerationOutput {
    const finalState =
      this.state.pendingCells.length === 0
        ? this.state.merged(this.input.precisionPolicy)
        : this.state
    return {
      ...this.input,
      meshNodes: [...finalState.acceptedNodes],
      rejectedCells: [...finalState.rejectedCells],
    }
  }

  override getConstructorParams() {
    return [this.input]
  }

  override visualize() {
    const output = this.getOutput()
    return visualizeMeshNodes(
      "Mesh Generation",
      output.problem,
      output.meshNodes,
      output.rejectedCells,
    )
  }
}

