import {
  BasePipelineSolver,
  definePipelineStep,
  type PipelineStep,
} from "@tscircuit/solver-utils"
import type { GraphicsObject } from "graphics-debug"
import type { PrecisionPolicy } from "@ohmx/geometry"
import { DEFAULT_PRECISION_POLICY } from "@ohmx/geometry"
import type { GridFill3DOptions } from "./solver/grid-fill-options"
import type { CapacityMeshNode } from "./types/capacity-mesh-types"
import type { SimpleRouteJson } from "./types/srj-types"
import { ProblemNormalizationSolver } from "./solver/problem-normalization-solver"
import { CellDecompositionSolver } from "./solver/cell-decomposition-solver"
import { MeshGenerationSolver } from "./solver/mesh-generation-solver"
import { GapFillSolver } from "./solver/gap-fill-solver"
import { OuterLayerMergeSolver } from "./solver/outer-layer-merge-solver"
import { visualizeMeshNodes, visualizeProblem } from "./solver/graphics"
import type {
  CellDecompositionOutput,
  GapFillOutput,
  MeshGenerationOutput,
  NormalizedProblemOutput,
  OuterLayerMergeOutput,
} from "./solver/pipeline-types"

export interface RectDiffPipelineInput {
  simpleRouteJson: SimpleRouteJson
  gridOptions?: Partial<GridFill3DOptions>
  precisionPolicy?: PrecisionPolicy
}

export class RectDiffPipeline extends BasePipelineSolver<RectDiffPipelineInput> {
  readonly inputProblem: RectDiffPipelineInput
  readonly precisionPolicy: PrecisionPolicy

  problemNormalizationSolver?: ProblemNormalizationSolver
  cellDecompositionSolver?: CellDecompositionSolver
  meshGenerationSolver?: MeshGenerationSolver
  gapFillSolver?: GapFillSolver
  outerLayerMergeSolver?: OuterLayerMergeSolver

  override pipelineDef: PipelineStep<any>[] = [
    definePipelineStep(
      "problemNormalizationSolver",
      ProblemNormalizationSolver,
      (pipeline: RectDiffPipeline) => [
        {
          simpleRouteJson: pipeline.inputProblem.simpleRouteJson,
          gridOptions: pipeline.inputProblem.gridOptions,
          precisionPolicy: pipeline.inputProblem.precisionPolicy,
        },
      ],
    ),
    definePipelineStep(
      "cellDecompositionSolver",
      CellDecompositionSolver,
      (pipeline: RectDiffPipeline) => [
        pipeline.getRequiredStageOutput<NormalizedProblemOutput>(
          "problemNormalizationSolver",
        ),
      ],
    ),
    definePipelineStep(
      "meshGenerationSolver",
      MeshGenerationSolver,
      (pipeline: RectDiffPipeline) => [
        pipeline.getRequiredStageOutput<CellDecompositionOutput>(
          "cellDecompositionSolver",
        ),
      ],
    ),
    definePipelineStep(
      "gapFillSolver",
      GapFillSolver,
      (pipeline: RectDiffPipeline) => [
        pipeline.getRequiredStageOutput<MeshGenerationOutput>(
          "meshGenerationSolver",
        ),
      ],
    ),
    definePipelineStep(
      "outerLayerMergeSolver",
      OuterLayerMergeSolver,
      (pipeline: RectDiffPipeline) => [
        pipeline.getRequiredStageOutput<GapFillOutput>("gapFillSolver"),
      ],
    ),
  ]

  constructor(inputProblem: RectDiffPipelineInput) {
    super(inputProblem)
    this.inputProblem = inputProblem
    this.precisionPolicy = inputProblem.precisionPolicy ?? DEFAULT_PRECISION_POLICY
  }

  getOutput(): { meshNodes: CapacityMeshNode[] } {
    const merged =
      this.getStageOutput<OuterLayerMergeOutput>("outerLayerMergeSolver")
    if (merged) {
      return {
        meshNodes: merged.outputNodes.map((node) => node.toCapacityMeshNode()),
      }
    }

    const gapFill = this.getStageOutput<GapFillOutput>("gapFillSolver")
    if (gapFill) {
      return {
        meshNodes: gapFill.outputNodes.map((node) => node.toCapacityMeshNode()),
      }
    }

    const meshGeneration =
      this.getStageOutput<MeshGenerationOutput>("meshGenerationSolver")
    if (meshGeneration) {
      return {
        meshNodes: meshGeneration.meshNodes.map((node) =>
          node.toCapacityMeshNode(),
        ),
      }
    }

    return { meshNodes: [] }
  }

  override initialVisualize(): GraphicsObject | null {
    const normalization =
      this.getStageOutput<NormalizedProblemOutput>("problemNormalizationSolver")
    if (normalization) {
      return visualizeProblem("RectDiff Pipeline", normalization.problem)
    }
    return null
  }

  override finalVisualize(): GraphicsObject | null {
    const merged =
      this.getStageOutput<OuterLayerMergeOutput>("outerLayerMergeSolver")
    if (merged) {
      return visualizeMeshNodes(
        "RectDiff Final Output",
        merged.problem,
        merged.outputNodes,
        merged.rejectedCells,
      )
    }
    return null
  }

  override getConstructorParams() {
    return [this.inputProblem]
  }

  private getRequiredStageOutput<T>(stageName: string): T {
    const output = this.getStageOutput<T>(stageName)
    if (!output) {
      throw new Error(`Missing required stage output: ${stageName}`)
    }
    return output
  }
}

